let scenarioEditorInstance;
async function editScenarioDescription(test){const {createScenarioEditorUI}=await import('/scenario-editor.js');scenarioEditorInstance??=createScenarioEditorUI({onSaved:async()=>{await load();toast('Opis scenariusza zapisany.');},onError:message=>toast(message)});await scenarioEditorInstance.open(test.project,test.id);}
// Wspólny wybór motywu dla lokalnych paneli na 127.0.0.1 (cookie współdzielone między portami).
(() => {
  const key = 'qa_ui_theme';
  const allowed = ['auto', 'light', 'dark'];
  const system = window.matchMedia('(prefers-color-scheme: dark)');
  const select = document.querySelector('#qa-theme-mode');
  function read() {
    try {
      const cookie = document.cookie.split(';').map(part => part.trim()).find(part => part.startsWith(key + '='));
      const value = cookie ? decodeURIComponent(cookie.slice(key.length + 1)) : localStorage.getItem(key);
      return allowed.includes(value) ? value : 'auto';
    } catch { return 'auto'; }
  }
  function apply(value) {
    document.documentElement.dataset.theme = value === 'auto' ? (system.matches ? 'dark' : 'light') : value;
    document.documentElement.dataset.themePreference = value;
    if (select) select.value = value;
  }
  function refresh() { apply(read()); }
  select?.addEventListener('change', () => {
    const value = allowed.includes(select.value) ? select.value : 'auto';
    try { localStorage.setItem(key, value); } catch {}
    try { document.cookie = key + '=' + value + '; Path=/; Max-Age=31536000; SameSite=Strict'; } catch {}
    apply(value);
  });
  system.addEventListener('change', refresh);
  window.addEventListener('focus', refresh);
  window.addEventListener('storage', event => { if (event.key === key) refresh(); });
  document.addEventListener('visibilitychange', () => { if (!document.hidden) refresh(); });
  refresh();
})();

import {createCollectionUI} from '/collections.js';
import {createIssueUI} from '/issues.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state,view='overview',page=0,search='',projectFilter='',typeFilter='',suiteFilter='',selected=new Set(),formAction=null,runnerProject='octopus',runnerUrl='';
const labels={collections:['Kolekcje JSON','Twoje lokalne kolekcje Postmana, pliki JSON i opisy OpenAPI.'],issues:['Zgłoszenia Redmine','Połącz zgłoszenie, scenariusz i dowody z wykonania.'],overview:['Przegląd','Wszystkie projekty i sprawdzenia w jednym miejscu.'],projects:['Projekty','Wspólny warsztat testowy wszystkich projektów.'],tests:['Katalog testów','Znajdź scenariusz, zapisz sprawdzenie lub przygotuj zestaw.'],suites:['Zestawy testów','Twoje listy scenariuszy do wspólnego sprawdzania.'],runner:['Uruchomienia','Uruchamiaj automaty w istniejących panelach projektów.'],checks:['Sprawdzenia poprawek','Zapisuj, co zostało sprawdzone i jaki był rezultat.'],history:['Historia','Wykonania automatów i zapisane sprawdzenia ręczne.']};
const statusNames={PASS:'Zaliczony',PASSED:'Zaliczony',COMPLETED:'Zakończony',FAIL:'Niezaliczony',FAILED:'Niezaliczony',BLOCKED:'Zablokowany',SKIP:'Pominięty',SKIPPED:'Pominięty',RUNNING:'W trakcie',CANCELLED:'Zatrzymany',INTERRUPTED:'Przerwany',INCOMPLETE:'Niepełny',UNKNOWN:'Brak wyniku'};
const badge=s=>`<span class="badge ${esc(Object.hasOwn(statusNames,s)?s:'UNKNOWN')}">${esc(statusNames[s]||s||'Brak wyniku')}</span>`;
const name=id=>state.projects.find(p=>p.id===id)?.name||id;
const date=v=>v?new Date(v).toLocaleString('pl-PL',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}):'Brak daty';
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json','X-Center-Token':$('meta[name=center-token]').content},body:JSON.stringify(body)}:{});const data=await r.json();if(!r.ok)throw new Error(data.error||'Błąd połączenia');return data;}
async function load(){state=await api('/api/state');$('#test-count').textContent=state.tests.length;$('#warnings').innerHTML=state.warnings.map(w=>`<div class="warning">${esc(w)}</div>`).join('');render();}
const allHistory=()=>[...state.history,...state.checks.map(x=>({...x,source:'Sprawdzenie ręczne'}))].sort((a,b)=>String(b.date).localeCompare(String(a.date)));
const options=(items,value='')=>items.map(([id,label])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(label)}</option>`).join('');
const projectOptions=()=>options(state.projects.map(p=>[p.id,p.name]),projectFilter);
function empty(title,body,button=''){return `<div class="empty"><strong>${title}</strong>${body}${button}</div>`;}
function projectCard(p){return `<article class="card project-card"><div class="project-top"><div class="project-icon ${p.id}">${p.id==='cms'?'K':p.id==='octopus'?'O':'H'}</div><div><h3>${p.name}</h3><span class="badge manual">Folder podłączony</span></div></div><p>${p.description}</p><div class="project-meta"><div><strong>${state.tests.filter(t=>t.project===p.id).length}</strong>${p.id==='hurtownia'?'zestawów API i testów ręcznych':'scenariuszy w katalogu'}</div><div><strong>${state.checks.filter(t=>t.project===p.id).length}</strong>sprawdzeń ręcznych</div></div><div class="actions"><button class="secondary" data-catalog="${p.id}">Przeglądaj testy →</button><button class="primary" data-runner="${p.id}">Przejdź do panelu testów →</button></div></article>`;}
function activity(rows){return rows.length?`<div class="card">${rows.map(x=>`<div class="activity"><div><strong>${esc(x.title)}</strong><p>${esc(name(x.project))} · ${esc(date(x.date))} · ${esc(x.source)}</p></div>${badge(x.status)}</div>`).join('')}</div>`:empty('Tu pojawią się wykonania','Zapisz pierwsze sprawdzenie lub uruchom automat w panelu projektu.');}
function render(){if(!state)return;view=location.hash.slice(1).split('/')[0]||'overview';if(!labels[view])view='overview';$('#heading').textContent=labels[view][0];$('#subtitle').textContent=labels[view][1];document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.dataset.view===view));const c=$('#content');
 if(view==='overview')c.innerHTML=`<div class="stats"><div class="stat"><label>Podłączone projekty</label><strong>${state.projects.length}</strong><small>${state.projects.map(p=>esc(p.name)).join(" · ")}</small></div><div class="stat"><label>Pozycje w katalogu</label><strong>${state.tests.length}</strong><small>Scenariusze i zestawy API</small></div><div class="stat"><label>Sprawdzenia ręczne</label><strong>${state.checks.length}</strong><small>Z zapisanym wynikiem i kontekstem</small></div><div class="stat"><label>Wykonania w historii</label><strong>${allHistory().length}</strong><small>Zaimportowane i zapisane tutaj</small></div></div><div class="section-head"><h2>Twoje projekty</h2><a href="#projects">Wszystkie projekty →</a></div><div class="project-grid">${state.projects.map(projectCard).join('')}</div><div class="two-col"><div><div class="section-head"><h2>Ostatnia aktywność</h2><a href="#history">Pełna historia →</a></div>${activity(allHistory().slice(0,5))}</div><div><div class="section-head"><h2>Szybkie sprawdzenie</h2></div><div class="card guide"><h3>Mała poprawka, pełny ślad.</h3><p>Zapisz kroki, oczekiwania i rezultat. Dołącz dowód i wróć do sprawdzenia przy kolejnym wydaniu.</p><div class="step"><b>1</b> Wskaż projekt i poprawkę</div><div class="step"><b>2</b> Opisz sposób sprawdzenia</div><div class="step"><b>3</b> Zapisz wynik i załączniki</div><p><button class="primary" data-new-check>+ Sprawdź poprawkę</button></p></div></div></div>`;
 if(view==='projects')c.innerHTML=`<div class="project-grid">${state.projects.map(projectCard).join('')}</div><div class="callout">Katalog Octopusa pochodzi z istniejącego indeksu scenariuszy. Hurtownia jest pokazana na poziomie zestawów API. Szczegółowe przypadki Hurtowni są dostępne w raportach projektu. Katalog CMS jest odczytywany bezpośrednio z plików Playwright.</div>`;
 if(view==='collections')c.innerHTML=collectionUI.render();
 if(view==='issues')c.innerHTML=issueUI.render();
 if(view==='tests')renderTests();
 if(view==='suites')c.innerHTML=`<div class="toolbar"><a href="#tests">Wybierz testy w katalogu, aby utworzyć zestaw →</a></div>${state.suites.length?state.suites.map(s=>`<article class="card suite-card"><h3>${esc(s.title)}</h3><p>${s.testIds.length} pozycji · ${esc(date(s.date))}</p><button class="secondary" data-suite="${s.id}">Otwórz listę testów</button></article>`).join(''):empty('Pierwszy zestaw czeka na Ciebie','Zaznacz scenariusze w katalogu i wybierz „Zapisz zestaw”.')}`;
 if(view==='checks')c.innerHTML=`<div class="toolbar"><span class="count">${state.checks.length} zapisanych sprawdzeń</span><button class="primary" data-new-check>+ Nowe sprawdzenie</button><button class="secondary" data-new-test>+ Test ręczny</button></div>${state.checks.length?historyTable(state.checks):empty('Zadbaj o ślad po każdej poprawce','Wprowadź kroki, wynik i dowody sprawdzenia.','<br><button class="primary" data-new-check>+ Pierwsze sprawdzenie</button>')}`;
 if(view==='history')c.innerHTML=`<div class="callout">Historia automatów jest odczytywana z raportów podłączonych projektów. Wynik całego zestawu nie oznacza automatycznie zaliczenia każdego scenariusza. Raporty otwierają się po uruchomieniu panelu danego projektu.</div><div class="toolbar"><input id="history-search" placeholder="Szukaj w historii…"><select id="history-project"><option value="">Wszystkie projekty</option>${projectOptions()}</select></div><div class="toolbar"><button class="secondary" id="cleanup-reports">Wyczyść nieprzypięte raporty</button><button class="secondary" id="restore-reports">Archiwum raportów / przywróć</button><span class="count">Czyszczenie porządkuje historię Centrum; pliki raportów pozostają na dysku.</span></div><div id="history-table">${historyTable(allHistory())}</div>`;
 if(view==='runner')c.innerHTML=`<div class="toolbar">${state.projects.map(p=>`<button class="${p.id===runnerProject?'primary':'secondary'}" data-runner="${p.id}">${p.name}</button>`).join('')}${runnerUrl?`<a href="${runnerUrl}" target="_blank" rel="noopener">Otwórz w osobnej karcie ↗</a>`:''}</div><div class="callout">To istniejący panel projektu z jego konfiguracją, logowaniem i blokadami. Otwarcie panelu nie uruchamia testów. Zestawy zapisane w Centrum są listami do sprawdzania; automaty uruchamiasz tutaj według dostępnych opcji projektu.</div>${runnerUrl?`<iframe class="runner-frame" title="Panel uruchamiania ${name(runnerProject)}" src="${runnerUrl}"></iframe>`:empty('Wybierz projekt','Przycisk powyżej uruchomi lokalny panel projektu.')}`;
}
function filteredTests(){return state.tests.filter(t=>(!projectFilter||t.project===projectFilter)&&(!typeFilter||t.type===typeFilter)&&(!suiteFilter||state.suites.find(s=>s.id===suiteFilter)?.testIds.includes(t.id))&&`${t.title} ${t.code} ${t.module} ${t.tags.join(' ')}`.toLowerCase().includes(search.toLowerCase()));}
function catalogRow(t){
 const last=state.checks.find(x=>x.testId===t.id);
 return `<tr><td class="catalog-selection"><input type="checkbox" data-select="${esc(t.id)}" aria-label="Zaznacz ${esc(t.code)}" ${selected.has(t.id)?'checked':''}></td>
 <td class="catalog-description" data-label="Scenariusz"><button class="link catalog-title" data-test="${esc(t.id)}">${esc(t.title)}</button><div class="catalog-meta"><code>${esc(t.code)}</code><span>${esc(t.module)}</span></div>${t.tags.length?`<div class="catalog-tags">${t.tags.slice(0,4).map(tag=>`<span class="tag">#${esc(tag)}</span>`).join('')}</div>`:''}</td>
 <td class="catalog-project" data-label="Projekt i typ"><span class="catalog-project-name" data-project="${esc(t.project)}">${esc(name(t.project))}</span><span class="badge ${t.type==='manual'?'manual':'auto'}">${t.type==='manual'?'Ręczny':'Automat'}</span></td>
 <td class="catalog-last-check" data-label="Ostatnie sprawdzenie ręczne">${last?badge(last.status)+`<small>${esc(date(last.date))}</small>`:'<span class="catalog-no-check">Brak sprawdzenia</span>'}</td>
 <td class="catalog-actions" data-label="Działania"><div class="catalog-row-actions"><button class="secondary catalog-check-button" data-check-test="${esc(t.id)}">Zapisz wynik ręczny</button><button type="button" class="secondary" data-edit-scenario="${esc(t.id)}">Edytuj scenariusz</button></div></td></tr>`;
}
function renderTests(){
 const rows=filteredTests(),pages=Math.max(1,Math.ceil(rows.length/40));page=Math.min(page,pages-1);
 $('#content').innerHTML=`<div class="toolbar catalog-toolbar"><input id="search" aria-label="Szukaj testu" placeholder="Szukaj po nazwie, ID lub tagu…" value="${esc(search)}"><select id="project-filter" aria-label="Projekt"><option value="">Wszystkie projekty</option>${projectOptions()}</select><select id="type-filter" aria-label="Typ testu">${options([['','Wszystkie typy'],['automatic','Automatyczne'],['manual','Ręczne']],typeFilter)}</select><button class="secondary" data-new-test>+ Test ręczny</button></div><div class="toolbar catalog-selection-bar"><span class="count">${rows.length} pozycji · zaznaczono ${selected.size}${suiteFilter?' · widok zestawu':''}</span><button class="secondary" id="save-suite" ${selected.size?'':'disabled'}>Zapisz zestaw</button>${suiteFilter?'<button class="secondary" id="clear-suite">Wszystkie testy</button>':''}</div>
 <div class="table-wrap catalog-table-wrap"><table class="catalog-table" aria-label="Katalog testów"><colgroup><col class="catalog-col-select"><col><col class="catalog-col-project"><col class="catalog-col-check"><col class="catalog-col-actions"></colgroup><thead><tr><th><input id="select-page" type="checkbox" aria-label="Zaznacz stronę"></th><th scope="col">Scenariusz</th><th scope="col">Projekt / typ</th><th scope="col">Sprawdzenie ręczne</th><th scope="col">Działania</th></tr></thead><tbody>${rows.slice(page*40,page*40+40).map(catalogRow).join('')}</tbody></table>${rows.length?'':'<div class="empty">Brak testów pasujących do filtrów.</div>'}</div>
 <div class="pager"><button class="secondary" id="prev" ${page?'':'disabled'} aria-label="Poprzednia strona">←</button>Strona ${page+1} z ${pages}<button class="secondary" id="next" ${page+1<pages?'':'disabled'} aria-label="Następna strona">→</button></div>`;
}

async function previewReportCleanup(restoring=false){
 const project=$('#history-project')?.value||'';
 const plan=await api('/api/reports/cleanup-preview?project='+encodeURIComponent(project));
 const rows=restoring?plan.archived:plan.candidates;
 const title=restoring?'Przywróć raporty z archiwum':'Wyczyść nieprzypięte raporty';
 const summary=`<p>Projekt: <strong>${esc(project?name(project):'Wszystkie projekty')}</strong></p><p>${restoring?'Do przywrócenia':'Do przeniesienia do archiwum'}: <strong>${rows.length}</strong>. Chronione powiązaniami: <strong>${plan.protectedCount}</strong>. W trakcie lub bez końcowego wyniku: <strong>${plan.activeCount}</strong>.</p><div class="callout">Raporty przypięte do zgłoszeń, zapisanych sprawdzeń lub opisów scenariuszy pozostają w historii. Czyszczenie ukrywa wpisy tylko w Centrum testów. Pliki i historia w panelach projektów pozostają bez zmian; nie zwalnia to miejsca na dysku.</div>`;
 const table=rows.length?`<div class="cleanup-report-list"><table><thead><tr><th>Raport</th><th>Projekt</th><th>Wynik</th><th>Data</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.title)}</td><td>${esc(name(r.project))}</td><td>${badge(r.status)}</td><td>${esc(date(r.date))}</td></tr>`).join('')}</tbody></table></div>`:'<p>Nie ma raportów pasujących do tej operacji.</p>';
 openModal(title,summary+table+(rows.length?'<label class="cleanup-confirm"><input name="confirmReports" type="checkbox" required> Potwierdzam operację na raportach z powyższej listy.</label>':''),rows.length?async()=>{const result=await api(restoring?'/api/reports/restore':'/api/reports/archive',{project,revision:plan.revision,confirm:true});toast((restoring?'Przywrócono raporty: ':'Przeniesiono raporty do archiwum: ')+result.count);}:null);
 $('#save').textContent=restoring?'Przywróć raporty':'Przenieś do archiwum';
}
function historyTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Sprawdzenie / przebieg</th><th>Projekt</th><th>Wynik</th><th>Data</th><th></th></tr></thead><tbody>${rows.map(x=>`<tr><td class="title">${esc(x.title)}<small>${esc(x.source||'Sprawdzenie ręczne')} · ${esc(x.environment||'')} ${x.version?'· '+esc(x.version):''}${x.bug?' · '+esc(x.bug):''}</small></td><td>${esc(name(x.project))}</td><td>${badge(x.status)}</td><td>${esc(date(x.date))}</td><td>${x.report?`<button class="link" data-report="${esc(x.id)}">Raport →</button>`:`<button class="link" data-check-detail="${x.id}">Szczegóły →</button>`}</td></tr>`).join('')}</tbody></table></div>`:empty('Brak zapisanych wykonań','Wyniki pojawią się po zapisaniu sprawdzenia lub odświeżeniu raportów.');}
function field(label,key,type='text',value='',required=true){return `<label class="field">${label}${type==='textarea'?`<textarea name="${key}" ${required?'required':''}>${esc(value)}</textarea>`:`<input type="${type}" name="${key}" value="${esc(value)}" ${required?'required':''} maxlength="${type==='text'?'500':'20000'}">`}</label>`;}
function openModal(title,html,action){$('#save').textContent='Zapisz';$('#dialog-title').textContent=title;$('#fields').innerHTML=html;$('#form-error').textContent='';$('#save').hidden=!action;$('#cancel').textContent=action?'Anuluj':'Zamknij';formAction=action;$('#modal').showModal();}
function newTest(prefill={}){openModal('Nowy test ręczny',field('Nazwa scenariusza','title','text',prefill.title||'')+`<div class="field-row"><label class="field">Projekt<select name="project">${options(state.projects.map(p=>[p.id,p.name]),prefill.project||projectFilter||'octopus')}</select></label>${field('Moduł','module','text','Poprawki')}</div>`+field('Kroki i warunki wstępne','steps','textarea',prefill.steps||'')+field('Oczekiwany rezultat','expected','textarea',prefill.expected||'')+field('Tagi oddzielone przecinkami','tags','text','',false),async b=>{await api('/api/tests',b);toast('Test ręczny zapisany');});}
function newCheck(test,issue,environment='dev'){openModal(test?'Sprawdź scenariusz':'Sprawdzenie poprawki',field('Nazwa sprawdzenia','title','text',test?.title||'')+`<div class="field-row"><label class="field">Projekt<select name="project" ${test?'disabled':''}>${options(state.projects.map(p=>[p.id,p.name]),test?.project||projectFilter||'octopus')}</select></label>${field('Numer błędu / zadania (opcjonalnie)','bug','text',issue?'#'+issue.number:'',false)}</div><div class="field-row">${issue?'<label class="field">Środowisko<select name="environment" required>'+options([['DEV','DEV'],['TEST','TEST']],environment.toUpperCase())+'</select></label>':field('Środowisko','environment','text','DEV')}${field('Wersja aplikacji / numer wydania','version')}</div>`+field('Co i w jaki sposób sprawdzono','steps','textarea',test?.steps||'')+field('Oczekiwany rezultat','expected','textarea',test?.expected||'')+field('Rzeczywisty rezultat','actual','textarea')+`<label class="field">Wynik<select name="status">${options([['PASS','Zaliczony'],['FAIL','Niezaliczony'],['BLOCKED','Zablokowany'],['SKIP','Pominięty']])}</select></label><label class="field">Dowody — maks. 5 plików, do 2 MB każdy<input type="file" id="attachments" multiple></label>`,async b=>{b.project=test?.project||b.project;b.testId=test?.id;b.issueId=issue?.id;const files=[...$('#attachments').files];if(files.length>5)throw new Error('Dodaj maksymalnie 5 plików.');b.attachments=await Promise.all(files.map(async f=>{if(f.size>2*1024*1024)throw new Error('Plik '+f.name+' przekracza 2 MB.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(f);});return {name:f.name,data};}));await api('/api/checks',b);toast('Sprawdzenie i dowody zapisane lokalnie');});}
function detailCheck(id){const x=state.checks.find(c=>c.id===id);openModal(x.title,`<p>${badge(x.status)} ${esc(name(x.project))} · ${esc(date(x.date))}</p>${[['Błąd / zadanie',x.bug],['Środowisko i wersja',x.environment+' · '+x.version],['Sposób sprawdzenia',x.steps],['Oczekiwany rezultat',x.expected],['Rzeczywisty rezultat',x.actual],['Scenariusz w chwili wykonania',x.snapshot?JSON.stringify(x.snapshot,null,2):'Sprawdzenie samodzielne']].map(([k,v])=>`<div class="detail-label">${k}</div><div class="detail-block">${esc(v||'—')}</div>`).join('')}<div class="detail-label">Dowody</div>${x.attachments.map(f=>`<p><a href="/attachments/${f.id}">↓ ${esc(f.name)}</a></p>`).join('')||'<p>Bez załączników</p>'}<button type="button" class="secondary" id="convert" data-id="${x.id}">Utwórz test ręczny z tego sprawdzenia</button>`,null);}
async function runner(id){runnerProject=id;runnerUrl='';location.hash='runner';render();toast('Otwieranie lokalnego panelu…');const result=await api('/api/runner',{project:id});runnerUrl=result.url;if(view==='runner')render();}
document.addEventListener('click',async e=>{const b=e.target.closest('button,a');if(!b)return;try{
 if(b.dataset.editScenario){await editScenarioDescription(state.tests.find(t=>t.id===b.dataset.editScenario));return;}
 await issueUI.click(b);await collectionUI.click(b);
 if(b.id==='quick'||b.hasAttribute('data-new-check'))newCheck();
 if(b.hasAttribute('data-new-test'))newTest();
 if(['close','cancel'].includes(b.id))$('#modal').close();
 if(b.id==='cleanup-reports'){await previewReportCleanup();return;}
 if(b.id==='restore-reports'){await previewReportCleanup(true);return;}
 if(b.id==='refresh'){await load();toast('Katalog i historia odświeżone');}
 if(b.dataset.catalog){projectFilter=b.dataset.catalog;suiteFilter='';page=0;location.hash='tests';render();}
 if(b.dataset.runner)await runner(b.dataset.runner);
 if(b.dataset.checkTest)newCheck(state.tests.find(t=>t.id===b.dataset.checkTest));
 if(b.dataset.test){const t=state.tests.find(t=>t.id===b.dataset.test);openModal(t.title,`<p><span class="badge auto">${esc(name(t.project))}</span></p>${[['ID',t.code],['Źródło',t.source||'Test utworzony w Centrum'],['Plik',t.file?`${t.file}:${t.line}`:'—'],['Kroki',t.steps||'Kroki automatu znajdują się w kodzie i dokumentacji projektu.'],['Oczekiwany rezultat',t.expected||'Warunki sprawdzające są zapisane w kodzie automatu.']].map(([k,v])=>`<div class="detail-label">${k}</div><div class="detail-block">${esc(v)}</div>`).join('')}<button type="button" class="primary" id="detail-check" data-id="${esc(t.id)}">Zapisz sprawdzenie</button>`,null);}
 if(b.id==='detail-check'){const t=state.tests.find(t=>t.id===b.dataset.id);$('#modal').close();newCheck(t);}
 if(b.dataset.checkDetail)detailCheck(b.dataset.checkDetail);
 if(b.id==='convert'){const x=state.checks.find(x=>x.id===b.dataset.id);$('#modal').close();newTest(x);}
 if(b.id==='save-suite')openModal('Zapisz zestaw',field('Nazwa zestawu','title')+`<p>${selected.size} zaznaczonych pozycji</p>`,async body=>{await api('/api/suites',{...body,testIds:[...selected]});selected.clear();toast('Zestaw zapisany');});
 if(b.dataset.suite){suiteFilter=b.dataset.suite;search='';projectFilter='';typeFilter='';page=0;location.hash='tests';render();}
 if(b.id==='clear-suite'){suiteFilter='';renderTests();}
 if(b.id==='prev'){page--;renderTests();}if(b.id==='next'){page++;renderTests();}
 if(b.dataset.report){const x=state.history.find(x=>x.id===b.dataset.report);await runner(x.project);runnerUrl=x.report;render();}
 }catch(error){toast(error.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const pos=e.target.selectionStart;search=e.target.value;page=0;renderTests();$('#search').focus();$('#search').setSelectionRange(pos,pos);}if(e.target.id==='history-search')filterHistory();});
function filterHistory(){const q=$('#history-search').value.toLowerCase(),p=$('#history-project').value;$('#history-table').innerHTML=historyTable(allHistory().filter(x=>(!p||x.project===p)&&`${x.title} ${x.bug||''} ${x.version||''}`.toLowerCase().includes(q)));}
document.addEventListener('change',e=>{if(e.target.id==='project-filter'){projectFilter=e.target.value;page=0;renderTests();}if(e.target.id==='type-filter'){typeFilter=e.target.value;page=0;renderTests();}if(e.target.dataset.select){e.target.checked?selected.add(e.target.dataset.select):selected.delete(e.target.dataset.select);renderTests();}if(e.target.id==='select-page'){filteredTests().slice(page*40,page*40+40).forEach(t=>e.target.checked?selected.add(t.id):selected.delete(t.id));renderTests();}if(e.target.id==='history-project')filterHistory();});
$('#form').addEventListener('submit',async e=>{e.preventDefault();if(!formAction)return;$('#save').disabled=true;$('#form-error').textContent='';try{await formAction(Object.fromEntries(new FormData(e.target)));$('#modal').close();await load();}catch(error){$('#form-error').textContent=error.message;}finally{$('#save').disabled=false;}});
const issueUI=createIssueUI({getState:()=>state,esc,field,options,badge,date,api,load,toast,openModal,newCheck,detailCheck,runner,openReport:async run=>{await runner(run.project);runnerUrl=run.report;render();}});
const collectionUI=createCollectionUI({getState:()=>state,esc,field,options,date,openModal,api,toast});
window.addEventListener('hashchange',render);load().catch(e=>{$('#content').textContent='Nie udało się otworzyć bazy: '+e.message;});

/* QA_GUIDE_START */
// Wspólna instrukcja obsługi. Adapter projektu dostarcza rzeczywiste dane testu.
function installQaGuide(config) {
  const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list = values => `<ol>${values.filter(Boolean).map(value => `<li>${escape(value)}</li>`).join('')}</ol>`;
  const section = (title, content) => `<section><h3>${title}</h3>${content}</section>`;
  const legend = `<dl class="qa-guide-legend"><dt>PASS / Zaliczone</dt><dd>Wykonane kontrole spełniły oczekiwania. Otwórz raport i potwierdź, że zawiera wybrany test.</dd><dt>FAIL / Niezaliczone</dt><dd>Kontrola nie przeszła lub wystąpił problem z jej wykonaniem. Odczytaj przyczynę; sam czerwony wynik nie rozstrzyga, czy winna jest aplikacja, dane czy połączenie.</dd><dt>SKIP / Pominięte</dt><dd>Nie sprawdzono tego warunku. To nie jest potwierdzenie poprawności.</dd><dt>BLOCKED / Zablokowane</dt><dd>Brakuje warunku potrzebnego do wykonania. Uzupełnij wskazane dane lub dostęp.</dd><dt>INCOMPLETE / Niepełne</dt><dd>Sprawdzono część zakresu; pozostałe warunki nadal wymagają wykonania.</dd></dl>`;
  const dialog = document.createElement('dialog');
  dialog.className = 'qa-guide-dialog';
  dialog.setAttribute('aria-labelledby', 'qa-guide-title');
  document.body.append(dialog);
  let returnFocus;
  dialog.addEventListener('click', event => { if (event.target.closest('[data-guide-close]')) dialog.close(); });
  dialog.addEventListener('close', () => { if (returnFocus?.isConnected) returnFocus.focus(); });
  function show(test, opener) {
    returnFocus = opener;
    const manual = test.type === 'manual';
    const steps = Array.isArray(test.steps) ? test.steps : test.steps ? [test.steps] : [];
    const expected = Array.isArray(test.expected) ? test.expected : test.expected ? [test.expected] : [];
    const effect = test.effect || config.effect;
    const actions = manual
      ? ['Przeczytaj warunki i oczekiwany wynik poniżej.', 'Wykonaj opisane kroki w testowanej aplikacji.', 'W Centrum wybierz „Zapisz wynik ręczny”, wpisz rzeczywisty rezultat i dołącz dowody. Zapisz wynik zgodny z obserwacją.']
      : test.actions || config.actions;
    dialog.innerHTML = `<div class="qa-guide-head"><div><small>INSTRUKCJA TESTU · ${escape(config.name)}</small><h2 id="qa-guide-title">${escape(test.title)}</h2></div><button type="button" class="secondary" data-guide-close>Zamknij</button></div>`
      + section('1. Co sprawdzamy?', `<p>${escape(test.purpose || test.title)}</p>${test.scope ? `<p>${escape(test.scope)}</p>` : ''}`)
      + section('2. Co przygotować?', list(test.prepare || config.prepare))
      + section('3. Co kliknąć i co się stanie?', list(actions) + `<p class="qa-guide-effect"><strong>Wpływ na dane:</strong> ${escape(effect)}</p>`)
      + section(manual ? '4. Kroki do wykonania ręcznie' : '4. Co zrobi automat?', (manual ? '' : '<p>Po uruchomieniu poniższe czynności wykonuje program. Nie musisz samodzielnie wysyłać zapytań ani klikać w testowanej aplikacji.</p>') + (steps.length ? list(steps) : `<p>Szczegółowe kroki tego przypadku nie zostały jeszcze opisane w katalogu. Sprawdź zakres w dokumentacji projektu przed uruchomieniem; ta karta nie zastępuje pełnego opisu testu.</p>`))
      + section('5. Jakiego wyniku oczekiwać?', expected.length ? list(expected) : `<p>Automat ocenia warunki dotyczące scenariusza „${escape(test.title)}”. Katalog nie zawiera osobnego, pełnego opisu oczekiwanego rezultatu. Nie potwierdzaj całej funkcjonalności wyłącznie na podstawie nazwy testu.</p>`)
      + section('6. Gdzie jest wynik i co zrobić dalej?', `<p>${escape(test.result || config.result)}</p>${legend}<p>Do zgłoszenia przypnij raport z tego uruchomienia, wskaż faktycznie wykonane ID testów, środowisko i wersję aplikacji. Dla błędu opisz oczekiwany i rzeczywisty rezultat. Samo dodanie testu do zgłoszenia nie potwierdza poprawki.</p>`)
      + `<div class="qa-guide-foot"><p>Ta instrukcja nie uruchamia testu ani nie zmienia wyboru.</p><button type="button" class="secondary" data-guide-close>Wróć do panelu</button></div>`;
    dialog.showModal();
  }
  const intro = document.createElement('details');
  intro.className = 'qa-guide-intro';
  intro.innerHTML = `<summary>Pierwszy raz tutaj? Jak wybrać test i odczytać wynik</summary><div class="qa-guide-intro-body"><h3>${escape(config.name)} — od czego zacząć</h3>${list(config.intro)}<h3>Co oznacza wynik?</h3>${legend}<p><strong>Słownik:</strong> scenariusz = jeden opisany przypadek; zestaw = grupa testów; środowisko = adres sprawdzanej aplikacji; API = sprawdzanie poprzez zapytania zamiast klikania w przeglądarce; raport = zapis przebiegu i dowody.</p><p>Przy testach wybierz „Jak wykonać test?”, aby poznać przygotowanie, zakres, wpływ na dane i dalsze kroki.</p></div>`;
  const main = document.querySelector('main');
  const header = main?.querySelector(':scope > header');
  if (header) header.after(intro); else main?.prepend(intro);
  function button(test, host) {
    if (!host || host.querySelector(':scope > [data-qa-guide]')) return;
    const b = document.createElement('button');
    b.type = 'button'; b.className = 'secondary qa-guide-button'; b.dataset.qaGuide = 'true';
    b.textContent = 'Jak wykonać test?';
    b.setAttribute('aria-label', 'Jak wykonać test: ' + test.title);
    b.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); show(test, b); });
    host.append(b);
  }
  let pending = false;
  function refresh() {
    pending = false;
    config.decorate(button);
    const authorFields = document.querySelector('#modal[open] #fields');
    if (authorFields && document.querySelector('#dialog-title')?.textContent === 'Nowy test ręczny' && !authorFields.querySelector('.qa-guide-author')) {
      const note = document.createElement('p');
      note.className = 'qa-guide-effect qa-guide-author';
      note.textContent = 'Napisz instrukcję dla osoby, która pierwszy raz widzi aplikację: gdzie wejść, jakie dane przygotować, co kolejno kliknąć i jaki komunikat lub zapis ma się pojawić. Opisz również wpływ na dane i co posprzątać po próbie. Oczekiwany wynik podaj konkretnie, np. „Zapis jest zablokowany, a nowe zamówienie nie powstaje”.';
      authorFields.prepend(note);
    }
    for (const control of document.querySelectorAll(config.launchSelector || '[data-no-launch-control]')) {
      if (control.closest('.qa-guide-dialog')) continue;
      let note = control.parentElement.querySelector(':scope > .qa-guide-before-run');
      if (!note) { note = document.createElement('p'); note.className = 'qa-guide-before-run'; control.after(note); }
      const text = config.launchNote();
      if (note.textContent !== text) note.textContent = text;
    }
  }
  function queue() { if (!pending) { pending = true; setTimeout(refresh, 30); } }
  const observer = new MutationObserver(records => { if (records.some(record => !record.target.closest?.('.qa-guide-dialog,.qa-guide-intro,.qa-guide-before-run,.qa-guide-button'))) queue(); });
  if (main) observer.observe(main, {childList:true,subtree:true});
  document.addEventListener('change', queue);
  document.addEventListener('click', queue);
  refresh();
}

